import{_ as e,o as l,c as i,a0 as a}from"./chunks/framework.ZP6uZ4uc.js";const u=JSON.parse('{"title":"Milestones（里程碑）","description":"","frontmatter":{},"headers":[],"relativePath":"milestones/index.md","filePath":"milestones/index.md","lastUpdated":null}'),o={name:"milestones/index.md"};function n(r,t,s,d,h,p){return l(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="milestones-里程碑" tabindex="-1">Milestones（里程碑） <a class="header-anchor" href="#milestones-里程碑" aria-label="Permalink to &quot;Milestones（里程碑）&quot;">​</a></h1><p>每个 Milestone 原则上应能在 AI 辅助下 <strong>2 小时内完成</strong>，并形成可保存的成果。</p><hr><h2 id="milestone-列表" tabindex="-1">Milestone 列表 <a class="header-anchor" href="#milestone-列表" aria-label="Permalink to &quot;Milestone 列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Milestone</th><th>周次</th><th>通过标准</th></tr></thead><tbody><tr><td>M1</td><td>数据清洗与描述</td><td>Week 1</td><td>能读取 CSV、处理数据问题、画图、解释模式</td></tr><tr><td>M2</td><td>概率模拟</td><td>Week 2</td><td>模拟需求、重复 1000 次、估计未满足需求</td></tr><tr><td>M3</td><td>抽样不确定性</td><td>Week 3</td><td>Bootstrap CI、正确解释置信区间</td></tr><tr><td>M4</td><td>可靠预测基线</td><td>Week 4</td><td>Baseline + 线性回归、正确切分、误差分析</td></tr><tr><td>M5</td><td>识别过拟合与泄漏</td><td>Week 5</td><td>制造泄漏实验、解释树深度影响</td></tr><tr><td>M6</td><td>纯预测项目</td><td>Week 6</td><td>独立项目、README、limitations</td></tr><tr><td>M7</td><td>第一个 LP 模型</td><td>Week 7</td><td>变量/目标/约束清楚、求解状态正确</td></tr><tr><td>M8</td><td>第一个 MIP 模型</td><td>Week 8</td><td>Binary variable 正确、LP vs MIP 比较</td></tr><tr><td>M9</td><td>纯优化项目</td><td>Week 9</td><td>敏感性分析、结果可视化</td></tr><tr><td>M10</td><td>预测+优化集成</td><td>Week 10</td><td>四种策略比较、decision quality 评价</td></tr></tbody></table><hr><h2 id="详细通过标准" tabindex="-1">详细通过标准 <a class="header-anchor" href="#详细通过标准" aria-label="Permalink to &quot;详细通过标准&quot;">​</a></h2><h3 id="milestone-1-数据清洗与描述" tabindex="-1">Milestone 1: 数据清洗与描述 <a class="header-anchor" href="#milestone-1-数据清洗与描述" aria-label="Permalink to &quot;Milestone 1: 数据清洗与描述&quot;">​</a></h3><p><strong>任务：</strong> 清洗共享单车数据并进行基础描述</p><p><strong>通过标准：</strong></p><ul><li>[ ] 能读取 CSV</li><li>[ ] 能处理至少两类数据问题（缺失值、异常值、重复行）</li><li>[ ] 能画出三种基础图（折线图、柱状图、散点图）</li><li>[ ] 能用自然语言解释一个模式和一个异常</li><li>[ ] Notebook 从头运行无错误</li></ul><hr><h3 id="milestone-2-概率模拟" tabindex="-1">Milestone 2: 概率模拟 <a class="header-anchor" href="#milestone-2-概率模拟" aria-label="Permalink to &quot;Milestone 2: 概率模拟&quot;">​</a></h3><p><strong>任务：</strong> 模拟单车需求与库存不足</p><p><strong>通过标准：</strong></p><ul><li>[ ] 正确生成随机需求（使用合适的分布）</li><li>[ ] 重复模拟至少 1,000 次</li><li>[ ] 估计平均未满足需求</li><li>[ ] 画出模拟结果分布</li><li>[ ] 解释增加库存的收益为何逐渐减小</li></ul><hr><h3 id="milestone-3-抽样不确定性" tabindex="-1">Milestone 3: 抽样不确定性 <a class="header-anchor" href="#milestone-3-抽样不确定性" aria-label="Permalink to &quot;Milestone 3: 抽样不确定性&quot;">​</a></h3><p><strong>任务：</strong> 使用 bootstrap 估计平均需求的置信区间</p><p><strong>通过标准：</strong></p><ul><li>[ ] 能正确重抽样</li><li>[ ] 输出点估计和区间</li><li>[ ] 不把 95% CI 错说成&quot;参数有 95% 概率在区间内&quot;</li><li>[ ] 能解释样本量变化对区间宽度的影响</li></ul><hr><h3 id="milestone-4-可靠预测基线" tabindex="-1">Milestone 4: 可靠预测基线 <a class="header-anchor" href="#milestone-4-可靠预测基线" aria-label="Permalink to &quot;Milestone 4: 可靠预测基线&quot;">​</a></h3><p><strong>任务：</strong> 建立并比较两个 baseline 和一个线性回归模型</p><p><strong>通过标准：</strong></p><ul><li>[ ] 明确预测时点</li><li>[ ] 正确切分数据（时间切分或随机切分并说明理由）</li><li>[ ] 报告 MAE 或 RMSE</li><li>[ ] 模型与 baseline 比较</li><li>[ ] 给出至少一个残差图或错误案例分析</li></ul><hr><h3 id="milestone-5-识别过拟合与泄漏" tabindex="-1">Milestone 5: 识别过拟合与泄漏 <a class="header-anchor" href="#milestone-5-识别过拟合与泄漏" aria-label="Permalink to &quot;Milestone 5: 识别过拟合与泄漏&quot;">​</a></h3><p><strong>任务：</strong> 设计一个正常实验和一个故意泄漏的实验</p><p><strong>通过标准：</strong></p><ul><li>[ ] 能说明泄漏变量为何不可用</li><li>[ ] 能比较训练和验证表现</li><li>[ ] 能解释树深度对过拟合的影响</li><li>[ ] 使用 Pipeline 或清晰的预处理流程</li></ul><hr><h3 id="milestone-6-纯预测项目" tabindex="-1">Milestone 6: 纯预测项目 <a class="header-anchor" href="#milestone-6-纯预测项目" aria-label="Permalink to &quot;Milestone 6: 纯预测项目&quot;">​</a></h3><p><strong>任务：</strong> 完成一个独立的预测项目</p><p><strong>通过标准：</strong></p><ul><li>[ ] 有清晰 README</li><li>[ ] 至少一个 baseline 和两个模型</li><li>[ ] 数据切分合理</li><li>[ ] 结果可复现</li><li>[ ] 有 limitations 章节</li><li>[ ] 不用测试集调参</li></ul><hr><h3 id="milestone-7-第一个-lp-模型" tabindex="-1">Milestone 7: 第一个 LP 模型 <a class="header-anchor" href="#milestone-7-第一个-lp-模型" aria-label="Permalink to &quot;Milestone 7: 第一个 LP 模型&quot;">​</a></h3><p><strong>任务：</strong> 建立资源分配或运输模型</p><p><strong>通过标准：</strong></p><ul><li>[ ] 变量、目标、约束和单位清楚</li><li>[ ] 求解状态为 optimal</li><li>[ ] 手工检查至少一条约束</li><li>[ ] 修改资源容量后，结果变化方向合理</li></ul><hr><h3 id="milestone-8-第一个-mip-模型" tabindex="-1">Milestone 8: 第一个 MIP 模型 <a class="header-anchor" href="#milestone-8-第一个-mip-模型" aria-label="Permalink to &quot;Milestone 8: 第一个 MIP 模型&quot;">​</a></h3><p><strong>任务：</strong> 完成指派或设施选址模型</p><p><strong>通过标准：</strong></p><ul><li>[ ] 正确使用 binary variable</li><li>[ ] 不出现明显缺失约束</li><li>[ ] 比较整数模型与 LP relaxation</li><li>[ ] 能解释为什么分数解在现实中不可执行</li></ul><hr><h3 id="milestone-9-纯优化项目" tabindex="-1">Milestone 9: 纯优化项目 <a class="header-anchor" href="#milestone-9-纯优化项目" aria-label="Permalink to &quot;Milestone 9: 纯优化项目&quot;">​</a></h3><p><strong>任务：</strong> 完成一个独立的优化项目</p><p><strong>通过标准：</strong></p><ul><li>[ ] 有现实情景</li><li>[ ] 有至少两个实验情景</li><li>[ ] 有敏感性分析</li><li>[ ] 有结果可视化</li><li>[ ] 能说明模型的一个关键假设和一个局限</li></ul><hr><h3 id="milestone-10-预测输出接入优化模型" tabindex="-1">Milestone 10: 预测输出接入优化模型 <a class="header-anchor" href="#milestone-10-预测输出接入优化模型" aria-label="Permalink to &quot;Milestone 10: 预测输出接入优化模型&quot;">​</a></h3><p><strong>任务：</strong> 用历史平均预测和 ML 预测分别驱动同一个优化模型</p><p><strong>通过标准：</strong></p><ul><li>[ ] 两种预测进入完全相同的优化模型</li><li>[ ] 在真实测试需求上计算最终运营成本</li><li>[ ] 不只比较预测指标，还比较决策指标</li><li>[ ] 包含 no-action benchmark 与 perfect-information benchmark</li></ul><hr><h2 id="检查表" tabindex="-1">检查表 <a class="header-anchor" href="#检查表" aria-label="Permalink to &quot;检查表&quot;">​</a></h2><p>👉 <a href="/orml/milestones/checklist">打印检查表</a></p>',59)])])}const c=e(o,[["render",n]]);export{u as __pageData,c as default};
